package com.featuredeliveryintelligence.fdi.runtime;
import java.util.*;
public final class GrafelBindingEvidence { private GrafelBindingEvidence(){} public static Map<String,Object> build(Map<String,Object> snapshot,Map<String,Object> attestation,String productOrScenarioId,String capturedAt,List<String> limitations){ StructuralIntelligence.validateSnapshotRef(snapshot);if(!"EXACTLY_BOUND".equals(attestation.get("result")))throw new RuntimeContractException("snapshot binding must be EXACTLY_BOUND");Map<String,Object>r=new LinkedHashMap<>();r.put("evidence_id","grafel-binding:"+snapshot.get("snapshot_id"));r.put("product_or_scenario_id",productOrScenarioId);r.put("snapshot",RuntimeMaps.copy(snapshot));r.put("attestation",RuntimeMaps.copy(attestation));r.put("captured_at",capturedAt);r.put("limitations",limitations==null?List.of():List.copyOf(limitations));r.put("result","EXACTLY_BOUND");return r;} }
